import RNA
t='.....(((((((...((((...((((...((((.........(((((............)))))...))))....((((..........))))...))))...(((........)))...))))..((......))...))))))).....'
# target pairs around 70-89: "((((..........))))" = 4bp helix
# positions: t[70:90]
print('70-90 target', t[70:90])
# Let me rebuild the structured candidate with proper assignment
stack=[]; pairs={}
for i,c in enumerate(t):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[j]=i; pairs[i]=j

# All helices: list opening runs and their closing runs
helices=[]
seen=set()
for i in range(151):
    if t[i]=='(' and i not in seen:
        j=i
        while j<151 and t[j]=='(': j+=1
        run_open=list(range(i,j))
        # closing run
        close=[]
        for o in run_open:
            close.append(pairs[o])
        close=sorted(close)
        for x in run_open+close: seen.add(x)
        helices.append((run_open,close))
for ho,hc in helices:
    print('open',ho,'close',hc,'len',len(ho))
